// Node 4: Lọc và Bóc Tách Danh Sách Link Bài Viết từ Crawl4AI
const inputItems = $input.all();
let currentSource = null;

try {
  currentSource = $('2. Duyệt từng Nguồn Tin').item.json;
} catch (e) {
  try {
    currentSource = $('2. Duyệt từng Nguồn Tin').first().json;
  } catch (err) {
    currentSource = { id: 0, source_name: 'Nguồn tin', source_category: 'Tin tức', source_url: '' };
  }
}

let allLinks = [];
for (const item of inputItems) {
  const res = item.json || {};
  const crawlResult = (Array.isArray(res.results) ? res.results[0] : (res.result || res.data || res)) || {};
  const linksObj = crawlResult.links || {};

  if (Array.isArray(linksObj.internal)) {
    for (const l of linksObj.internal) {
      if (typeof l === 'string') allLinks.push(l);
      else if (l && l.href) allLinks.push(l.href);
    }
  }
  if (Array.isArray(linksObj)) {
    for (const l of linksObj) {
      if (typeof l === 'string') allLinks.push(l);
      else if (l && l.href) allLinks.push(l.href);
    }
  }
}

const assetRegex = /\.(png|jpe?g|gif|webp|svg|css|js|ico|pdf|zip|mp4|mp3|docx?|xlsx?)(\?.*)?$/i;
const excludeKeywords = [
  '/tag/', '/tags/', '/chuyen-muc/', '/category/', '/dieu-khoan', '/lien-he', '/gioi-thieu',
  '/rss', '/video', '/photo', '/infographic', '/login', '/dang-nhap', '/dang-ky',
  'facebook.com', 'twitter.com', 'youtube.com', 'zalo.me', 'linkedin.com', 'tiktok.com',
  'javascript:', 'mailto:', 'tel:', '#'
];

const sourceUrlClean = (currentSource.source_url || '').replace(/\/+$/, '');
const seen = new Set();
const candidateUrls = [];

for (const rawUrl of allLinks) {
  if (!rawUrl || typeof rawUrl !== 'string') continue;
  let url = rawUrl.trim().split('#')[0];
  if (url.startsWith('//')) url = 'https:' + url;
  if (!url.startsWith('http://') && !url.startsWith('https://')) continue;
  if (url.replace(/\/+$/, '') === sourceUrlClean) continue;
  if (assetRegex.test(url)) continue;
  if (excludeKeywords.some(kw => url.toLowerCase().includes(kw))) continue;

  // Kiểm tra bài viết hợp lệ
  const isArticle = /\-[0-9]{4,}/.test(url) || /\/\d{4}\/\d{2}\//.test(url) || (/\.(chn|html|htm)$/i.test(url) && url.split('/').pop().length > 20);

  if (isArticle && !seen.has(url)) {
    seen.add(url);
    candidateUrls.push({
      json: {
        candidate_url: url,
        source_id: currentSource.id,
        source_name: currentSource.source_name,
        source_category: currentSource.source_category,
        source_url: currentSource.source_url
      }
    });
  }
}

// Giới hạn 6 bài mới nhất mỗi nguồn
return candidateUrls.slice(0, 6);

