// Node 9: Bóc Tách Chi Tiết: Tiêu đề, Nội dung, Ngày xuất bản, Tác giả
const itemData = $input.first().json || {};
let articleMeta = {};
try {
  articleMeta = $('6. Kiểm tra Trùng lặp (Postgres)').item.json || {};
} catch (e) {
  try {
    articleMeta = $('5. Duyệt từng Bài Viết').item.json || {};
  } catch (err) {
    articleMeta = {};
  }
}

const crawlRes = (Array.isArray(itemData.results) ? itemData.results[0] : (itemData.result || itemData.data || itemData)) || {};
const metadata = crawlRes.metadata || {};
const mdObj = crawlRes.markdown || {};

// 1. LẤY NỘI DUNG
let cleanContent = '';
if (typeof mdObj === 'string') {
  cleanContent = mdObj;
} else if (mdObj.fit_markdown && mdObj.fit_markdown.length > 50) {
  cleanContent = mdObj.fit_markdown;
} else if (mdObj.raw_markdown) {
  cleanContent = mdObj.raw_markdown;
} else if (crawlRes.content) {
  cleanContent = crawlRes.content;
}

// 2. LẤY TIÊU ĐỀ
let title = metadata.title || metadata.ogTitle || metadata['og:title'] || '';
if (!title && cleanContent) {
  const hMatch = cleanContent.match(/^#{1,3}\s+(.+)$/m);
  if (hMatch && hMatch[1].trim().length > 5) {
    title = hMatch[1].trim();
  }
}
title = (title || 'Bài viết từ ' + (articleMeta.source_name || 'Nguồn tin')).replace(/\s*[-|–—]\s*(?:Báo|Trang tin)?[A-Za-zÀ-Ỹà-ỹ0-9\s\.]+\.(?:vn|com)$/i, '').trim();

// 3. LẤY NGÀY XUẤT BẢN
let publishedDate = null;
const rawDate = metadata['article:published_time'] || metadata.pubdate || metadata.publishedTime || metadata.date || null;
if (rawDate) {
  const d = new Date(rawDate);
  if (!isNaN(d.getTime())) publishedDate = d.toISOString();
}
if (!publishedDate && cleanContent) {
  const dateMatch = cleanContent.match(/([0-3]?[0-9][\/\-\.] [0-1]?[0-9][\/\-\.] [1-2][0-9]{3})/);
  if (dateMatch) {
    const parts = dateMatch[1].split(/[\/\-\.]/);
    if (parts.length === 3) {
      const d = new Date(`${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}T07:00:00+07:00`);
      if (!isNaN(d.getTime())) publishedDate = d.toISOString();
    }
  }
}

// 4. LẤY TÁC GIẢ
let author = metadata.author || metadata['article:author'] || '';
if (!author && cleanContent) {
  const aMatch = cleanContent.match(/(?:Tác giả|Nguồn|Theo|PV)[\s:]+([A-ZÀ-Ỹ][a-zà-ỹ0-9\s\.]{2,30})/i);
  if (aMatch) author = aMatch[1].trim();
}
if (!author) author = articleMeta.source_name || 'Ban Biên Tập';

// 5. TÓM TẮT & CẢM XÚC
let summary = metadata.description || metadata.ogDescription || '';
if (!summary && cleanContent) {
  const paras = cleanContent.split(/\n\s*\n/).map(p => p.trim()).filter(p => p.length > 30);
  if (paras.length > 0) summary = paras[0].slice(0, 300) + '...';
}

let sentiment = 'Trung lập';
const textLower = (title + ' ' + summary).toLowerCase();
if (['tăng mạnh', 'tăng trưởng', 'khởi sắc', 'kỷ lục', 'lợi nhuận', 'bứt phá'].some(w => textLower.includes(w))) {
  sentiment = 'Tích cực';
} else if (['giảm sâu', 'lao dốc', 'thua lỗ', 'khó khăn', 'bắt giữ', 'vỡ nợ'].some(w => textLower.includes(w))) {
  sentiment = 'Tiêu cực';
}

const finalUrl = articleMeta.candidate_url || crawlRes.url || '';

return [{
  json: {
    url: finalUrl,
    title: title.slice(0, 500),
    summary: summary.slice(0, 1000),
    content_raw: cleanContent.slice(0, 50000),
    published_date: publishedDate,
    author: String(author).slice(0, 100),
    source_name: articleMeta.source_name || '',
    source_category: articleMeta.source_category || 'Tin tức',
    source_url: articleMeta.source_url || '',
    sentiment: sentiment,
    tags: [articleMeta.source_category || 'Tin tức'],
    metadata: metadata
  }
}];
